// Des: Audits every store vendor weekly and queues repairs
// Flo: list every vendor in parallel > a key the Db knows but a vendor lacks, or holds at another size, is queued for copy > a few keys are compared byte for byte > keys no pack row knows are only counted
// I/O: Fanz (vendors, Db, clock) > Ares counts; runs at most once per purg_veri_days; never deletes anything
// ===================================================================
const std = @import("std"); const stor = @import("sy-clou-stor.zig"); const quot = @import("sy-mirr-quot.zig"); const fail = @import("ru-fail-over.zig"); const mirr = @import("sy-mirr-stor.zig");
const CF = .{ .dayz = 86400000, .audt = "mirr_audt", .audc = "mirr_audc" };
pub const Ares = struct { quer: u32 = 0, orph: u32 = 0, bads: u32 = 0, ranz: bool = false };
const Lstz = struct { stoz: stor.Stor, iozz: std.Io, objs: [mirr.PREF.len][]const stor.Objz = @splat(&.{}), errz: ?anyerror = null, arnz: std.heap.ArenaAllocator };
const Deep = struct { prim: stor.Stor, stoz: stor.Stor, iozz: std.Io, keys: []const []const u8, bads: []bool, arnz: std.heap.ArenaAllocator };
fn lstzRunz(jobz: *Lstz) void { const allo = jobz.arnz.allocator(); for (mirr.PREF, 0..) |pre2, indx| { jobz.objs[indx] = jobz.stoz.list(jobz.stoz.ctx2, allo, jobz.iozz, pre2) catch |err3| { jobz.errz = err3; return; }; } }
fn deepRunz(jobz: *Deep) void { for (jobz.keys, 0..) |key2, indx| { _ = jobz.arnz.reset(.free_all); const allo = jobz.arnz.allocator(); const onez = jobz.prim.get(jobz.prim.ctx2, allo, jobz.iozz, key2) catch continue; const twoz = jobz.stoz.get(jobz.stoz.ctx2, allo, jobz.iozz, key2) catch { jobz.bads[indx] = true; continue; }; if (!std.mem.eql(u8, onez, twoz)) jobz.bads[indx] = true; } }
fn sizeMapz(aren: std.mem.Allocator, jobz: *const Lstz) !std.StringHashMapUnmanaged(u64) { var outp: std.StringHashMapUnmanaged(u64) = .empty; for (jobz.objs) |objs| { for (objs) |obj2| try outp.put(aren, obj2.key2, obj2.size); } return outp; }
pub fn fanzAudt(self: *mirr.Fanz, aren: std.mem.Allocator) !Ares { var rslt: Ares = .{}; const last = try fail.flagGetz(self.dbzz, CF.audt); if (last > 0 and self.nowz - last < @as(i64, self.conf.purg_veri_days) * CF.dayz) return rslt; const alls = try mirr.membAllz(self, aren); var jobs: std.ArrayList(Lstz) = .empty; var owns: std.ArrayList(usize) = .empty; for (alls, 0..) |mem, indx| { if (self.stat.dead[mem.idxz] or !try quot.opsaOkay(self.dbzz, mem.name, self.nowz, self.conf.clou_mirr_opsa_mont, mirr.PREF.len)) continue; try jobs.append(aren, .{ .stoz = mem.store, .iozz = self.iozz, .arnz = mirr.arenNewz() }); try owns.append(aren, indx); } if (jobs.items.len < 2 or owns.items[0] != 0) { for (jobs.items) |*jobz| jobz.arnz.deinit(); return rslt; } mirr.runzAllz(Lstz, lstzRunz, jobs.items); defer for (jobs.items) |*jobz| jobz.arnz.deinit(); for (jobs.items, owns.items) |jobz, indx| { try quot.opsaAddz(self.dbzz, alls[indx].name, self.nowz, mirr.PREF.len); if (jobz.errz) |err3| { if (indx == 0) return err3; self.stat.dead[alls[indx].idxz] = true; self.stat.errz[alls[indx].idxz] = err3; } } var live: std.StringHashMapUnmanaged(void) = .empty; { var stmt = try self.dbzz.prep("SELECT DISTINCT packk FROM pack;"); defer stmt.fini(); while (try stmt.step()) try live.put(aren, try aren.dupe(u8, stmt.colzText(0)), {}); } var want: std.StringArrayHashMapUnmanaged(u64) = .empty; for (jobs.items) |jobz| { if (jobz.errz != null) continue; for (jobz.objs) |objs| { for (objs) |obj2| { if (mirr.lateKeyz(obj2.key2) and !live.contains(obj2.key2)) { rslt.orph += 1; continue; } const slot = try want.getOrPut(aren, obj2.key2); if (!slot.found_existing) slot.value_ptr.* = obj2.size; } } }
    var maps: std.ArrayList(std.StringHashMapUnmanaged(u64)) = .empty; for (jobs.items) |*jobz| try maps.append(aren, try sizeMapz(aren, jobz)); for (jobs.items, owns.items, 0..) |jobz, indx, ind2| { if (jobz.errz != null) continue; const mem = alls[indx]; for (want.keys(), want.values()) |key2, sizz| { const have = maps.items[ind2].get(key2); if (have == null or have.? != sizz) { try mirr.queu(self, aren, mirr.CF.mput, mem.name, key2); rslt.quer += 1; } } } const nkey = want.count(); if (nkey > 0 and self.conf.purg_veri_cont > 0) { const star = @as(usize, @intCast(@max(try fail.flagGetz(self.dbzz, CF.audc), 0))) % nkey; const numz = @min(@as(usize, self.conf.purg_veri_cont), nkey); const keys = try aren.alloc([]const u8, numz); for (keys, 0..) |*item, indx| item.* = want.keys()[(star + indx) % nkey]; var deps: std.ArrayList(Deep) = .empty; var dwns: std.ArrayList(usize) = .empty; for (jobs.items, owns.items, 0..) |jobz, indx, ind2| { if (indx == 0 or jobz.errz != null) continue; const pick = try aren.alloc(bool, numz); var cnt2: usize = 0; for (keys, 0..) |key2, ind3| { pick[ind3] = maps.items[0].get(key2) != null and maps.items[ind2].get(key2) != null; if (pick[ind3]) cnt2 += 1; } if (cnt2 == 0) continue; const subz = try aren.alloc([]const u8, cnt2); const subb = try aren.alloc(bool, cnt2); @memset(subb, false); var fill: usize = 0; for (keys, 0..) |key2, ind3| { if (pick[ind3]) { subz[fill] = key2; fill += 1; } } try deps.append(aren, .{ .prim = alls[0].store, .stoz = alls[indx].store, .iozz = self.iozz, .keys = subz, .bads = subb, .arnz = mirr.arenNewz() }); try dwns.append(aren, indx); } mirr.runzAllz(Deep, deepRunz, deps.items); defer for (deps.items) |*jobz| jobz.arnz.deinit(); for (deps.items, dwns.items) |jobz, indx| { for (jobz.keys, jobz.bads) |key2, badz| { if (badz) { try mirr.queu(self, aren, mirr.CF.mput, alls[indx].name, key2); rslt.bads += 1; } } } try fail.flagSetz(self.dbzz, CF.audc, @intCast(star + numz)); } try fail.flagSetz(self.dbzz, CF.audt, self.nowz); rslt.ranz = true; return rslt; }
